Test test_a2_global_mix("a2.global.mix", []() {
	RNG rng(2266524198);

	Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 2));

	constexpr uint32_t operations = 10;

	for (uint32_t i = 0; i < operations; i++) {

