function allTests(dir = "tests") {
	const ret = [];
	const fs = require('fs');
	for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
		if (ent.isDirectory()) {
			ret.push(...allTests(dir + "/" + ent.name));
		} else if (ent.isFile() && ent.name.endsWith(".cpp")) {
			ret.push(maek.CPP(dir + "/" + ent.name));
		}
	}
	return ret;
}
