#include \"geometry/halfedge.h\"

#include <cmath>
#include <iostream>

int main() {
    Halfedge_Mesh mesh = Halfedge_Mesh::cube(1.0f);
    if (auto err = mesh.validate()) {
        std::cerr << \"initial invalid: \" << err->second << std::endl;
        return 1;
    }

    Vec3 before = Vec3(0.0f, 0.0f, 0.0f);
    for (auto f = mesh.faces.begin(); f "'!= mesh.faces.end(); ++f) {
        if (!f->boundary) {
            before = f->normal();
            break;
        }
    }

    mesh.flip_orientation();
    if (auto err = mesh.validate()) {
        std::cerr << "flip invalid: " << err->second << std::endl;
        return 1;
    }

    Vec3 after = Vec3(0.0f, 0.0f, 0.0f);
    for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
        if (!f->boundary) {
            after = f->normal();
            break;
        }
    }
    if (dot(before, after) > -0.5f) {
        std::cerr << "orientation did not flip normals" << std::endl;
        return 1;
    }

    mesh.set_corner_normals(30.0f);
    for (auto h = mesh.halfedges.begin(); h != mesh.halfedges.end(); ++h) {
        if (h->face->boundary) continue;
        float len = h->corner_normal.norm();
        if (!std::isfinite(len) || len < 0.9f || len > 1.1f) {
            std::cerr << "bad corner normal length" << std::endl;
            return 1;
        }
    }

    mesh.set_corner_uvs_per_face();
    for (auto h = mesh.halfedges.begin(); h != mesh.halfedges.end(); ++h) {
        if (h->face->boundary) continue;
        if (!std::isfinite(h->corner_uv.x) || !std::isfinite(h->corner_uv.y)) {
            std::cerr << "non-finite uv" << std::endl;
            return 1;
        }
        if (h->corner_uv.x < -1e-4f || h->corner_uv.x > 1.0001f ||
            h->corner_uv.y < -1e-4f || h->corner_uv.y > 1.0001f) {
            std::cerr << "uv out of range" << std::endl;
            return 1;
        }
    }

    return 0;
}
